<div class="page-header"><div><h2>Produções</h2><p>Registro de o que foi feito, por quem, quando, em qual oficina e em qual sequência.</p></div><a href="<?= e(url('/producoes/criar')) ?>" class="btn btn-primary">Nova Produção</a></div>
<section class="panel"><div class="panel-body"><div class="table-wrap"><table class="table"><thead><tr><th>Trabalho</th><th>Aluno</th><th>Produto</th><th>Oficina</th><th>Qtd.</th><th>Data</th><th>Situação</th><th>Responsável</th><?php if(is_professor()): ?><th>Ações</th><?php endif; ?></tr></thead><tbody>
<?php foreach($productions as $p): ?><tr><td><?= $p['work_number']?'nº '.e($p['work_number']):'—' ?></td><td><?php if($p['student_name']): ?><a class="text-link" href="<?= e(url('/alunos/'.$p['student_id'])) ?>"><?= e($p['student_name']) ?></a><?php else: ?><span class="muted">Registro antigo</span><?php endif; ?></td><td><a class="text-link" href="<?= e(url('/produtos/'.$p['product_id'])) ?>"><?= e($p['product_name']) ?></a></td><td><?= e($p['workshop_name']) ?></td><td><?= e($p['quantity']) ?></td><td><?= e(date('d/m/Y',strtotime($p['produced_at']))) ?></td><td><?= $p['delivery_id']?'<span class="badge badge-success">Entregue</span>':($p['availability_status']==='disponivel'?'<span class="badge badge-success">Disponível</span>':'<span class="badge">Indisponível</span>') ?></td><td><?= e($p['responsible_name']??'—') ?></td><?php if(is_professor()): ?><td><?php if($p['delivery_id']): ?><span class="badge">Histórico protegido</span><?php else: ?><div class="actions"><a class="btn btn-secondary" href="<?= e(url('/producoes/'.$p['id'].'/editar')) ?>">Editar</a><form method="POST" action="<?= e(url('/producoes/'.$p['id'].'/excluir')) ?>" data-confirm="Excluir esta produção?"><?= csrf_field() ?><button class="btn btn-danger">Excluir</button></form></div><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$productions): ?><tr><td colspan="9">Nenhuma produção registrada.</td></tr><?php endif; ?></tbody></table></div></div></section>
